/** Low-frequency studio-light calibration sampled from the user-provided reference.
 * This is an 128×128 blurred illumination field, not a displayed image. Colors are
 * baked onto real sheet/fiber vertices and move with their physical geometry.
 */
const size=128;
const bytes=Uint8Array.from(atob(''),c=>c.charCodeAt(0));
const linear=(v:number)=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4);
export function calibratedLightAt(p:number[]):[number,number,number] {
  const x=Math.max(0,Math.min(size-1,(p[0]*250+627)/1254*(size-1)));
  const y=Math.max(0,Math.min(size-1,(627-p[1]*250)/1254*(size-1)));
  const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy;
  const c=[0,1,2].map(k=>{
    const a=bytes[(iy*size+ix)*3+k],b=bytes[(iy*size+Math.min(ix+1,size-1))*3+k];
    const c=bytes[(Math.min(iy+1,size-1)*size+ix)*3+k],d=bytes[(Math.min(iy+1,size-1)*size+Math.min(ix+1,size-1))*3+k];
    return linear(((a+(b-a)*fx)*(1-fy)+(c+(d-c)*fx)*fy)/255);
  });
  return [c[0],c[1],c[2]];
}
